package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with optional category filter
func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortBy := r.URL.Query().Get("sort")

	// Build dynamic query
	baseQuery := "SELECT id, name, price, description FROM products WHERE active = true"
	var conditions []string

	if category != "" {
		// Developer note: category is from a controlled dropdown on frontend
		conditions = append(conditions, fmt.Sprintf("category = '%s'", category))
	}

	if minPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price >= %s", minPrice))
	}

	if len(conditions) > 0 {
		baseQuery += " AND " + strings.Join(conditions, " AND ")
	}

	// Apply sorting
	switch sortBy {
	case "price_asc":
		baseQuery += " ORDER BY price ASC"
	case "price_desc":
		baseQuery += " ORDER BY price DESC"
	case "name":
		baseQuery += " ORDER BY name ASC"
	default:
		baseQuery += " ORDER BY id DESC"
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		line := fmt.Sprintf(`  {"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
			id, name, price, description)
		w.Write([]byte(line))
	}
	w.Write([]byte("\n]"))
}

// healthCheck for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting product-search service on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
